/* global vega, lil */

'use strict';

// eslint-disable-next-line no-restricted-syntax
(function iife() {
	var throttledRerender; // Function for re-rendering a visualization
	var editorConfig;      // Object used for storing an editor configuration
	var TOGGLE_STATE;      // Current editor menu toggle state
	var ACK_INTERVAL;      // Number of milliseconds between requests to acknowledge received events
	var eventSource;       // Instance used to listen for server events
	var VERBOSE;           // Flag to indicate whether the application should be "chatty" in logging events
	var editor;            // Editor instance
	var schema;            // Visualization schema
	var lastID;            // Identifier of the last event received by the client
	var view;              // Vega visualization view instance
	var ack;               // Reference to an interval timer for performing periodic acknowledgment of received events

	VERBOSE = 1;
	lastID = -1;

	ACK_INTERVAL = 1000 * 60 * 10; // milliseconds

	// Set the initial editor menu toggle state:
	TOGGLE_STATE = false;

	// Initialize an object for storing an editor configuration:
	editorConfig = {
		'meta': {
			'Toggle Menus': toggleEditorFolders
		},
		'general': {
			'background': '',
			'description': '',
			'height': 0,
			'width': 0
		},
		'autosize': {},
		'axes': [],
		'data': [],
		'legends': [],
		'marks': [],
		'padding': {},
		'projections': [],
		'scales': [],
		'title': {}
	};

	throttledRerender = throttle( rerender, 1000 );

	/**
	* Executes a list of functions in series.
	*
	* @private
	* @param {Array<Function>} fcns - list of functions to execute
	* @param {Callback} clbk - callback to invoke upon completion
	* @returns {void}
	*/
	function series( fcns, clbk ) {
		var idx = -1;
		return next();

		/**
		* Executes the next function in the series.
		*
		* @private
		* @param {(Error|null)} error - error object
		* @returns {void}
		*/
		function next() {
			// Check for an error...
			if ( arguments[ 0 ] ) {
				return clbk( arguments[ 0 ] );
			}
			// Update the counter and check if we have run all functions...
			idx += 1;
			if ( idx >= fcns.length ) {
				return clbk();
			}
			// Invoke the next function:
			fcns[ idx ]( next );
		}
	}

	/**
	* Logs a message to the console.
	*
	* @private
	* @param {string} msg - message to log
	* @param {...*} [args] - additional arguments
	* @returns {void}
	*/
	function log() {
		var args;
		var i;
		if ( !VERBOSE ) {
			return;
		}
		args = [];
		for ( i = 0; i < arguments.length; i++ ) {
			args.push( arguments[ i ] );
		}
		console.log.apply( console, args );
	}

	/**
	* Returns a function which should only be invoked at most once per a specified interval.
	*
	* @private
	* @param {Function} fcn - function to wrap
	* @param {NonNegativeInteger} interval - number of milliseconds before a function can be invoked again
	* @returns {Function} wrapped function
	*/
	function throttle( fcn, interval ) { // TODO: make more robust and comprehensive and move to `@stdlib/function/throttle`
		var args;
		var flg;

		flg = false;
		return throttled;

		/**
		* Returns a throttled function.
		*
		* @private
		* @param {...*} [args] - arguments
		* @returns {void}
		*/
		function throttled() {
			var i;

			// Cache the latest list of arguments...
			args = [];
			for ( i = 0; i < arguments.length; i++ ) {
				args.push( arguments[ i ] );
			}
			// If the flag is already set, then we're paused...
			if ( flg ) {
				// Nothing left to do, but wait...
				return;
			}
			flg = true;

			// Start the timer for when we can invoke the throttled function:
			setTimeout( onTimeout, interval );
		}

		/**
		* Callback invoked after a delay.
		*
		* @private
		*/
		function onTimeout() {
			fcn.apply( null, args );

			// Now that the function was invoked, we can reset the flag:
			flg = false;
		}
	}

	/**
	* Renders a visualization.
	*
	* @private
	* @param {Object} spec - visualization specification
	* @returns {Promise} promise which resolves upon rendering a visualization
	*/
	function render( spec ) {
		view = new vega.View( vega.parse( spec ), {
			'renderer': 'svg',
			'container': '#main',
			'hover': true
		});
		return view.runAsync();
	}

	/**
	* Re-renders a visualization.
	*
	* @private
	* @param {Object} spec - visualization specification
	* @returns {Promise} promise which resolves upon rendering a visualization
	*/
	function rerender( spec ) {
		view.finalize();
		return render( spec );
	}

	/**
	* Displays a visualization.
	*
	* @private
	* @param {Callback} clbk - callback to invoke upon completion
	*/
	function displayVisualization( clbk ) {
		fetch( '/spec' )
			.then( onResponse )
			.then( onJSON )
			.then( onRender )
			.catch( onError );

		/**
		* Callback invoked upon receiving an HTTP response.
		*
		* @private
		* @param {Response} response - response object
		* @returns {Promise} promise which resolves upon converting response content to JSON
		*/
		function onResponse( response ) {
			return response.json();
		}

		/**
		* Callback invoked upon resolving a specification.
		*
		* @private
		* @param {Object} spec - visualization specification
		* @returns {Promise} promise which resolves upon rendering a visualization
		*/
		function onJSON( spec ) {
			schema = spec;
			return render( spec );
		}

		/**
		* Callback invoked upon rendering a visualization.
		*
		* @private
		* @returns {void}
		*/
		function onRender() {
			return clbk();
		}

		/**
		* Callback invoked upon encountering an error.
		*
		* @private
		* @param {Error} error - error object
		*/
		function onError( error ) {
			clbk( error );
		}
	}

	/**
	* Establishes a server connection for listening to events.
	*
	* @private
	* @param {Callback} clbk - callback to invoke upon completion
	*/
	function connect2server( clbk ) {
		eventSource = new EventSource( '/events', {
			'withCredentials': true
		});
		eventSource.addEventListener( 'error', onError );
		eventSource.addEventListener( 'open', onOpen );
		eventSource.addEventListener( 'ping', onPing );

		eventSource.addEventListener( 'data', onData );
		eventSource.addEventListener( 'patch', onPatch );
		eventSource.addEventListener( 'refresh', onRefresh );

		/**
		* Callback invoked upon a "data" event.
		*
		* @private
		* @param {Event} event - event object
		* @returns {void}
		*/
		function onData( event ) {
			log( 'Received a "data" event.' );
			lastID = event.id;

			// FIXME: create a Vega changeset, so we can avoid needing to re-initialize Vega
		}

		/**
		* Callback invoked upon a "patch" event.
		*
		* @private
		* @param {Event} event - event object
		* @returns {void}
		*/
		function onPatch( event ) {
			log( 'Received a "patch" event.' );
			lastID = event.id;

			// FIXME: need to update editor

			// FIXME: depending on changes, we may need to re-initialize the editor

			// FIXME: perform JSON patch (currently, we're receiving the entire schema)
			onRefresh( event ); // FIXME
		}

		/**
		* Callback invoked upon a "refresh" event.
		*
		* @private
		* @param {Event} event - event object
		* @returns {void}
		*/
		function onRefresh( event ) {
			log( 'Received a "refresh" event.' );
			lastID = event.id;
			schema = JSON.parse( event.data );
			throttledRerender( schema );

			// FIXME: this may need to be `reInitEditor` (e.g., if new axes/scales/datasets are added or axes/scales/datasets are removed, etc)
			refreshEditor();
		}

		/**
		* Callback invoked when unable to establish a server connection.
		*
		* @private
		* @param {Event} event - event object
		*/
		function onError() {
			var err = new Error( 'Failed to establish server connection.' );
			if ( ack ) {
				clearInterval( ack );
			}
			clbk( err );
		}

		/**
		* Callback invoked upon establishing a server connection.
		*
		* @private
		* @param {Event} event - event object
		*/
		function onOpen() {
			log( 'Established server connection.' );
			setInterval( sendAcknowledgment, ACK_INTERVAL );
			clbk();
		}

		/**
		* Callback invoked upon receiving a "ping" (keep-alive) message.
		*
		* @private
		*/
		function onPing() {
			log( 'Received a "ping" event.' );
		}
	}

	/**
	* Initializes an editor configuration.
	*
	* @private
	* @param {Callback} clbk - callback to invoke upon completion
	*/
	function initEditorConfig( clbk ) {
		syncEditorConfig();
		clbk();
	}

	/**
	* Synchronizes an editor configuration with the current schema.
	*
	* @private
	*/
	function syncEditorConfig() {
		syncEditorConfigGeneral();
		syncEditorConfigPadding();
		syncEditorConfigTitle();

		// TODO: sync each axis
	}

	/**
	* Synchronizes an editor configuration with the current schema.
	*
	* @private
	*/
	function syncEditorConfigGeneral() {
		editorConfig.general.background = schema.background || '#fff';
		editorConfig.general.description = schema.description || '';
		editorConfig.general.height = schema.height;
		editorConfig.general.width = schema.width;
	}

	/**
	* Synchronizes an editor configuration with the current schema.
	*
	* @private
	*/
	function syncEditorConfigPadding() {
		editorConfig.padding.bottom = schema.padding.bottom || 0;
		editorConfig.padding.left = schema.padding.left || 0;
		editorConfig.padding.right = schema.padding.right || 0;
		editorConfig.padding.top = schema.padding.top || 0;
	}

	/**
	* Synchronizes an editor configuration with the current schema.
	*
	* @private
	*/
	function syncEditorConfigTitle() {
		editorConfig.title.text = schema.title.text.join( '\n' );
		editorConfig.title.align = schema.title.align || '';
		editorConfig.title.fontSize = schema.title.fontSize || 0;
		editorConfig.title.fontStyle = schema.title.fontStyle || '';
		editorConfig.title.fontWeight = schema.title.fontWeight || '';
	}

	/**
	* Initializes an editor.
	*
	* @private
	* @param {Callback} clbk - callback to invoke upon completion
	*/
	function initEditor( clbk ) {
		log( 'Initializing editor...' );
		displayEditor();
		log( 'Editor initialized.' );
		clbk();
	}

	/**
	* Removes an editor.
	*
	* @private
	*/
	function removeEditor() {
		log( 'Removing editor...' );
		editor.destroy();
		log( 'Editor removed.' );
	}

	/**
	* Re-initializes an editor.
	*
	* @private
	*/
	function reInitEditor() { /* eslint-disable-line no-unused-vars */ // FIXME: remove once we use `reInitEditor`
		removeEditor();
		displayEditor();
	}

	/**
	* Displays an editor.
	*
	* @private
	*/
	function displayEditor() {
		editor = new lil.GUI({
			'width': 300
		});
		editor.title( 'Editor' );

		editor.add( editorConfig.meta, 'Toggle Menus' );
		addGeneralMenu( editor );
		addPaddingMenu( editor );
		addTitleMenu( editor );

		// TODO: for axes menus, we need to loop over each spec axis and create a dedicated sub-folder; if there are no axes, no folder grouping to display

		editor.onFinishChange( onEditorChange );
	}

	/**
	* Adds a "general" menu to an editor.
	*
	* @private
	* @param {Editor} editor - editor instance
	*/
	function addGeneralMenu( editor ) {
		var folder = editor.addFolder( 'General' );
		folder.close();

		folder.addColor( editorConfig.general, 'background' );
		folder.add( editorConfig.general, 'description' );
		folder.add( editorConfig.general, 'height', 0 );
		folder.add( editorConfig.general, 'width', 0 );
	}

	/**
	* Adds a "padding" menu to an editor.
	*
	* @private
	* @param {Editor} editor - editor instance
	*/
	function addPaddingMenu( editor ) {
		var folder = editor.addFolder( 'Padding' );
		folder.close();

		folder.add( editorConfig.padding, 'bottom', 0 );
		folder.add( editorConfig.padding, 'left', 0 );
		folder.add( editorConfig.padding, 'right', 0 );
		folder.add( editorConfig.padding, 'top', 0 );
	}

	/**
	* Adds a "title" menu to an editor.
	*
	* @private
	* @param {Editor} editor - editor instance
	*/
	function addTitleMenu( editor ) {
		var folder = editor.addFolder( 'Title' );
		folder.close();

		folder.add( editorConfig.title, 'align', [
			'',
			'left',
			'right',
			'center'
		]);
		folder.add( editorConfig.title, 'fontSize', 0 );
		folder.add( editorConfig.title, 'fontStyle' );
		folder.add( editorConfig.title, 'fontWeight', [
			'',
			'normal',
			'bold',
			'lighter',
			'bolder',
			'100',
			'200',
			'300',
			'400',
			'500',
			'600',
			'700',
			'800',
			'900'
		]);
		folder.add( editorConfig.title, 'text' );
	}

	/**
	* Callback invoked upon changing a value in the editor.
	*
	* @private
	* @param {Event} event - event object
	*/
	function onEditorChange( event ) {
		var opts;
		var url;
		var obj;
		var ns;

		// FIXME: other properties/objects

		obj = event.object;
		switch ( obj ) {
		case editorConfig.general:
			ns = '';
			break;
		case editorConfig.padding:
			ns = 'padding/';
			break;
		case editorConfig.title:
			ns = 'title/';
			break;
		default:
			break;
		}
		log( 'Editor changed: %s%s', ns, event.property );

		url = '/config/'+ns+event.property;
		opts = {
			'method': 'POST',
			'headers': {
				'Content-Type': 'text/plain'
			},
			'body': event.value,
			'credentials': 'same-origin'
		};

		log( 'Attempting to update configuration...' );
		fetch( url, opts )
			.then( onResponse )
			.catch( onError );

		/**
		* Callback invoked upon receiving an HTTP response.
		*
		* @private
		* @param {Response} response - response object
		* @returns {void}
		*/
		function onResponse( response ) {
			if ( response.ok ) {
				log( 'Successfully updated configuration.' );
				return;
			}
			console.error( 'Encountered an error when posting change. Status: %d.', response.status );
			refreshEditor();
		}

		/**
		* Callback invoked upon encountering an error.
		*
		* @private
		* @param {Error} error - error object
		*/
		function onError( error ) {
			console.error( 'Encountered an error when posting change. Error: %s.', error.message );
			refreshEditor();
		}
	}

	/**
	* Refreshes the editor.
	*
	* @private
	*/
	function refreshEditor() {
		log( 'Refreshing editor...' );
		syncEditorConfig();
		refreshEditorControllers();
		log( 'Editor refreshed.' );
	}

	/**
	* Refreshes editor controllers.
	*
	* @private
	*/
	function refreshEditorControllers() {
		var controllers;
		var i;

		controllers = editor.controllersRecursive();
		for ( i = 0; i < controllers.length; i++ ) {
			controllers[ i ].updateDisplay();
		}
	}

	/**
	* Toggles editor controllers.
	*
	* @private
	*/
	function toggleEditorFolders() {
		var folders;
		var method;
		var i;

		log( 'Toggling editor folders...' );

		TOGGLE_STATE = !TOGGLE_STATE;
		method = ( TOGGLE_STATE ) ? 'open' : 'close';

		folders = editor.foldersRecursive();
		for ( i = 0; i < folders.length; i++ ) {
			folders[ i ][ method ]();
		}
		log( 'Toggled editor folders.' );
	}

	/**
	* Sends an acknowledgment to the server regarding the last received event.
	*
	* @private
	*/
	function sendAcknowledgment() {
		var opts = {
			'method': 'POST',
			'body': lastID.toString(),
			'credentials': 'same-origin'
		};
		log( 'Sending acknowledgement to server...' );
		fetch( '/ack', opts )
			.then( onResponse )
			.catch( onError );

		/**
		* Callback invoked upon receiving an HTTP response.
		*
		* @private
		* @param {Response} response - response object
		* @returns {void}
		*/
		function onResponse( response ) {
			if ( response.ok ) {
				log( 'Successfully sent acknowledgment.' );
				return;
			}
			console.error( 'Encountered an error when sending acknowledgment. Status: %d.', response.status );
		}

		/**
		* Callback invoked upon encountering an error.
		*
		* @private
		* @param {Error} error - error object
		*/
		function onError( error ) {
			console.error( 'Encountered an error when sending acknowledgment. Error: %s.', error.message );
		}
	}

	/**
	* Callback invoked upon completion.
	*
	* @private
	* @param {Error} [error] - error object
	*/
	function done( error ) {
		if ( error ) {
			console.error( error.message );
			return;
		}
		log( 'Successfully initialized visualization.' );
	}

	// Main execution sequence:
	series([
		displayVisualization,
		connect2server,
		initEditorConfig,
		initEditor
	], done );
})();
